#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_conv_activation_bn_kernel(
    const float* input, const float* weight, const float* bias,
    const float* bn_weight, const float* bn_bias, const float* bn_running_mean, const float* bn_running_var, float eps,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_height, int in_width, int out_height, int out_width, int kernel_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_height * out_width;

    if (idx >= total_elements) return;

    // Calculate indices (NCHW layout)
    int tmp = idx;
    int w = tmp % out_width;
    tmp /= out_width;
    int h = tmp % out_height;
    tmp /= out_height;
    int c = tmp % out_channels;
    int n = tmp / out_channels;

    // Compute convolution
    float sum = bias[c];

    for (int ic = 0; ic < in_channels; ic++) {
        int in_offset = ((n * in_channels + ic) * in_height);
        int w_offset = ((c * in_channels + ic) * kernel_size);

        for (int kh = 0; kh < kernel_size; kh++) {
            int ih = h + kh;
            if (ih >= in_height) continue;

            for (int kw = 0; kw < kernel_size; kw++) {
                int iw = w + kw;
                if (iw >= in_width) continue;

                sum += input[in_offset + ih * in_width + iw] * 
                       weight[w_offset + kh * kernel_size + kw];
            }
        }
    }

    // Apply activation: tanh(softplus(x)) * x
    float softplus = logf(1.0f + expf(fminf(sum, 20.0f)));
    float tanh_val = tanhf(softplus);
    float act_output = tanh_val * sum;

    // Apply batchnorm: y = (x - running_mean) * (weight / sqrt(running_var + eps)) + bias
    float bn_scale = bn_weight[c] / sqrtf(bn_running_var[c] + eps);
    float bn_shift = bn_bias[c] - bn_running_mean[c] * bn_scale;

    output[idx] = act_output * bn_scale + bn_shift;
